css:
/* linktree: home shows section buttons, sections show their links, back button returns home */
[data-layout="linktree"] main {
    width: min(480px, 92vw);
    height: auto;
    min-height: 92vh;
}
[data-layout="linktree"] .terminal {
    border: none;
    background: transparent;
    box-shadow: none;
}
[data-layout="linktree"] .window-bar,
[data-layout="linktree"] .sidebar,
[data-layout="linktree"] .terminal-panel,
[data-layout="linktree"] .status-bar { display: none !important; }
[data-layout="linktree"] .body-split { flex-direction: column; }
[data-layout="linktree"] .preview-panel { background: transparent; }
[data-layout="linktree"] .preview-content {
    padding: 48px 32px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
}
[data-layout="linktree"] .preview-content .section-label { display: none; }
[data-layout="linktree"] .preview-content h1 { font-size: 2.2rem; margin-bottom: 8px; }
[data-layout="linktree"] .preview-content p:first-of-type { color: var(--muted); font-size: .95rem; margin-bottom: 32px; }

/* section buttons on home */
.section-btn {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    max-width: 360px;
    padding: 14px 20px;
    margin-bottom: 12px;
    background: var(--window);
    border: 1px solid var(--border);
    border-radius: 12px;
    color: var(--text);
    text-decoration: none;
    font-size: .95rem;
    transition: .2s;
    cursor: pointer;
}
.section-btn:hover {
    border-color: var(--accent);
    background: var(--hover);
    transform: translateY(-2px);
}
.section-btn .arrow { color: var(--accent); transition: .2s; }
.section-btn:hover .arrow { transform: translateX(4px); }

/* back button */
.back-btn {
    all: unset;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 24px;
    padding: 8px 16px;
    color: var(--muted);
    font-size: .85rem;
    transition: .2s;
}
.back-btn:hover { color: var(--accent); }
.back-btn .arrow { transition: .2s; }
.back-btn:hover .arrow { transform: translateX(-3px); }

/* link buttons (from renderLinks) */
.link-btn {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    max-width: 360px;
    padding: 14px 20px;
    margin-bottom: 12px;
    background: var(--window);
    border: 1px solid var(--border);
    border-radius: 12px;
    color: var(--text);
    text-decoration: none;
    font-size: .95rem;
    transition: .2s;
}
.link-btn:hover {
    border-color: var(--accent);
    background: var(--hover);
    transform: translateY(-2px);
}
.link-btn .arrow { color: var(--accent); transition: .2s; }
.link-btn:hover .arrow { transform: translateX(4px); }

.link-group { width: 100%; max-width: 360px; margin-bottom: 24px; }
.link-group-title {
    color: var(--muted-alt);
    font-size: .75rem;
    letter-spacing: .15em;
    text-transform: uppercase;
    margin-bottom: 10px;
    text-align: left;
}
.link-group-desc { color: var(--muted); font-size: .85rem; margin-bottom: 10px; text-align: left; }
